// tetris_scores.c - generated by split_c.py from tetris.c
#include "tetris_priv.h"



static const char *const s_titleRowName[TITLE_NUM_ROWS] = { "Start", "High Scores" };


// ---- High scores ----------------------------------------------------------

// Load the list (and names) from the save driver the first time they are needed.
static void HsEnsureLoaded(void)
{
    uint16_t i, j;

    if(tet_hsLoaded) return;
    tet_hsLoaded = true;

    if(!Memory_Read(MEM_SLOT_TETRIS_SCORES, &tet_hs, sizeof tet_hs))
        for(i = 0; i < TETRIS_NUM_SCORES; i++)
            tet_hs.score[i] = 0;                  // nothing saved yet

    if(!Memory_Read(MEM_SLOT_TETRIS_NAMES, &tet_hsn, sizeof tet_hsn))
        for(i = 0; i < TETRIS_NUM_SCORES; i++)
            for(j = 0; j < TETRIS_NAME_LEN; j++)
                tet_hsn.c[i][j] = ' ';            // old save: blank names

    // Sanitize: anything outside ' '..'Z' becomes a space.
    for(i = 0; i < TETRIS_NUM_SCORES; i++)
        for(j = 0; j < TETRIS_NAME_LEN; j++)
            if(tet_hsn.c[i][j] < ' ' || tet_hsn.c[i][j] > 'Z')
                tet_hsn.c[i][j] = ' ';
}


// Insert `score` into the top-5 list with a BLANK name and save right away,
// so the score is safe even if the player quits during name entry.
// Returns the rank 0..4, or -1 if it did not place. Blocks briefly (flash).
int16_t tet_HsSubmit(uint32_t score)
{
    int16_t i, j;
    int16_t rank = -1;

    HsEnsureLoaded();

    if(score == 0) return -1;

    for(i = 0; i < TETRIS_NUM_SCORES; i++)
    {
        if(score > tet_hs.score[i])
        {
            rank = i;
            break;
        }
    }
    if(rank < 0) return -1;

    for(i = TETRIS_NUM_SCORES - 1; i > rank; i--)
    {
        tet_hs.score[i] = tet_hs.score[i - 1];
        for(j = 0; j < TETRIS_NAME_LEN; j++)
            tet_hsn.c[i][j] = tet_hsn.c[i - 1][j];
    }
    tet_hs.score[rank] = score;
    for(j = 0; j < TETRIS_NAME_LEN; j++)
        tet_hsn.c[rank][j] = ' ';

    Memory_Write(MEM_SLOT_TETRIS_SCORES, &tet_hs,  sizeof tet_hs);
    Memory_Write(MEM_SLOT_TETRIS_NAMES,  &tet_hsn, sizeof tet_hsn);
    Memory_Flush();
    return rank;
}


// ---- Title screen helpers -------------------------------------------------

// One event per stick push: +1 / -1 when the axis crosses TETRIS_STICK_ON,
// then 0 until it has gone back inside TETRIS_STICK_OFF.
static int16_t TitleStickEdge(int16_t v, int16_t *state)
{
    int16_t target = *state;

    if(v >= TETRIS_STICK_ON)                                target = 1;
    else if(v <= -TETRIS_STICK_ON)                          target = -1;
    else if(v < TETRIS_STICK_OFF && v > -TETRIS_STICK_OFF)  target = 0;

    if(target != *state)
    {
        *state = target;
        return target;                  // 0 on release = "no event"
    }
    return 0;
}


// Centered text.
static void TitleText(const char *s, int16_t x, int16_t y, uint32_t color)
{
    Graphics_setForegroundColor(&g_sContext, color);
    Graphics_drawStringCentered(&g_sContext, (int16_t *)s, AUTO_STRING_LENGTH,
                                x, y, TRANSPARENT_TEXT);
}


// Left-aligned text; y is the vertical CENTRE of the line (same as TitleText).
static void TitleTextLeft(const char *s, int16_t x, int16_t y, uint32_t color)
{
    Graphics_setForegroundColor(&g_sContext, color);
    Graphics_drawString(&g_sContext, (int16_t *)s, AUTO_STRING_LENGTH,
                        x, y - 10, TRANSPARENT_TEXT);
}


static void TitleHeader(const char *title)
{
    Graphics_setBackgroundColor(&g_sContext, COLOR_BLACK);
    Graphics_setFont(&g_sContext, &g_sFontCmss20b);
    Graphics_clearDisplay(&g_sContext);

    TitleText(title, SCREEN_W / 2, 15, COLOR_WHITE);
    Graphics_drawLine(&g_sContext, 10, 30, SCREEN_W - 11, 30);
}


static void TitleDrawRow(uint16_t i)
{
    int16_t top = TETRIS_TITLE_ROW_Y0 + (int16_t)i * (TETRIS_TITLE_ROW_H + TETRIS_TITLE_ROW_GAP);
    bool    sel = (i == tet_titleSel);

    // Clear the whole band first: the selected rectangle is wider.
    Graphics_FillRect(TETRIS_TITLE_ROW_X0 - 12, top - 1,
                      TETRIS_TITLE_ROW_X1 + 12, top + TETRIS_TITLE_ROW_H, COLOR_BLACK);

    if(sel)
    {
        Graphics_FillRect(TETRIS_TITLE_ROW_X0 - 10, top,
                          TETRIS_TITLE_ROW_X1 + 10, top + TETRIS_TITLE_ROW_H - 1, COLOR_TETRIS_GRID);
        Graphics_FillRect(TETRIS_TITLE_ROW_X0 - 8,  top + 2,
                          TETRIS_TITLE_ROW_X1 + 8,  top + TETRIS_TITLE_ROW_H - 3, COLOR_TETRIS_T_PURPLE);
    }
    else
    {
        Graphics_FillRect(TETRIS_TITLE_ROW_X0, top,
                          TETRIS_TITLE_ROW_X1, top + TETRIS_TITLE_ROW_H - 1, COLOR_TETRIS_GHOST);
    }

    TitleText(s_titleRowName[i], SCREEN_W / 2, top + TETRIS_TITLE_ROW_H / 2,
              sel ? COLOR_WHITE : COLOR_TETRIS_GRID);
}
   // end TitleDrawRow

// Rank, name and score on one line. The font is proportional, so the three
// pieces are drawn separately at fixed x positions instead of padded with spaces.
static void TitleDrawScores(void)
{
    char     buf[24];
    char     nm[TETRIS_NAME_LEN + 1];
    int16_t  i, j, y;
    uint32_t col;

    for(i = 0; i < TETRIS_NUM_SCORES; i++)
    {
        y   = TETRIS_SCORE_Y0 + i * TETRIS_SCORE_PITCH;
        col = (i == 0) ? COLOR_GOLD : COLOR_WHITE;

        sprintf(buf, "%u.", (unsigned)(i + 1));
        TitleTextLeft(buf, 40, y, col);

        if(tet_hs.score[i] == 0)
        {
            TitleTextLeft("-", 75, y, col);
            continue;
        }

        for(j = 0; j < TETRIS_NAME_LEN; j++) nm[j] = (char)tet_hsn.c[i][j];
        nm[TETRIS_NAME_LEN] = 0;
        TitleTextLeft(nm, 75, y, col);

        sprintf(buf, "%lu", (unsigned long)tet_hs.score[i]);
        TitleTextLeft(buf, 195, y, col);
    }
}


// ---- Title screen: init / redraw ------------------------------------------

void tet_TitleInit(void)
{
    HsEnsureLoaded();
    tet_titleView      = TITLE_VIEW_MENU;
    tet_titleSel       = 0;
    tet_titleStickY    = 0;
    tet_titleDirtyFull = true;
    tet_titleDirtyRows = 0;
}


void tet_TitleRedraw(void)
{
    tet_titleDirtyFull = true;
}


// One event per stick push: returns v only on the frame it changes to nonzero.
static int16_t NameEdge(int16_t v, int16_t *prev)
{
    int16_t e = (v != 0 && v != *prev) ? v : 0;
    *prev = v;
    return e;
}


void tet_NameBegin(void)
{
    uint16_t i;

    for(i = 0; i < TETRIS_NAME_LEN; i++) tet_nameIdx[i] = 0;     // 'A'
    tet_nameCur        = 0;
    tet_nameStickX     = g_joy.dirX;     // a stick still held doesn't fire
    tet_nameStickY     = g_joy.dirY;
    tet_nameActive     = true;
    tet_nameDirtyFull  = true;
    tet_nameDirtyBoxes = true;
}


// Store the typed name at this game's rank, save, and go to the title.
static void NameFinish(void)
{
    uint16_t j;

    for(j = 0; j < TETRIS_NAME_LEN; j++)
        tet_hsn.c[tet_gameOverRank][j] = (uint16_t)tet_nameCharset[tet_nameIdx[j]];

    Memory_Write(MEM_SLOT_TETRIS_NAMES, &tet_hsn, sizeof tet_hsn);
    Memory_Flush();                       // blocks briefly (flash)
    Buzzer_PlaySfx(&sfx_menu_select);

    tet_nameActive = false;
    tet_inTitle    = true;
    tet_TitleInit();
}


// Logic only.
void tet_NameUpdate(void)
{
    int16_t sx = NameEdge(g_joy.dirX, &tet_nameStickX);
    int16_t sy = NameEdge(g_joy.dirY, &tet_nameStickY);   // +1 = down
    bool up    = (sy < 0);                       // MOVE = the stick
    bool down  = (sy > 0);
    bool left  = (sx < 0);
    bool right = (sx > 0);
    bool tap   = Ui_Select();                    // SELECT = BLUE / stick click: next letter / OK
    bool back  = Ui_Back();                      // BACK   = RED: previous letter

    if(back && tet_nameCur > 0)
    {
        tet_nameCur--;
        tet_nameDirtyBoxes = true;
        Buzzer_PlaySfx(&sfx_menu_back);
    }
    if(up)
    {
        tet_nameIdx[tet_nameCur] = (uint16_t)((tet_nameIdx[tet_nameCur] + 1) % NAME_NCHARS);
        tet_nameDirtyBoxes = true;
        Buzzer_PlaySfx(&sfx_menu_move);
    }
    if(down)
    {
        tet_nameIdx[tet_nameCur] = (uint16_t)((tet_nameIdx[tet_nameCur] + NAME_NCHARS - 1) % NAME_NCHARS);
        tet_nameDirtyBoxes = true;
        Buzzer_PlaySfx(&sfx_menu_move);
    }
    if(left && tet_nameCur > 0)
    {
        tet_nameCur--;
        tet_nameDirtyBoxes = true;
    }
    if(right && tet_nameCur < TETRIS_NAME_LEN - 1)
    {
        tet_nameCur++;
        tet_nameDirtyBoxes = true;
    }
    if(tap)
    {
        if(tet_nameCur < TETRIS_NAME_LEN - 1)
        {
            tet_nameCur++;
            tet_nameDirtyBoxes = true;
        }
        else
        {
            NameFinish();
        }
    }
}


// Drawing only.
void tet_NameRender(void)
{
    char     buf[24];
    char     ch[2];
    uint16_t i;
    int16_t  x;
    bool     sel;

    if(tet_nameDirtyFull)
    {
        tet_nameDirtyFull = false;
        TitleHeader((tet_gameOverRank == 0) ? "NEW #1 HIGH SCORE!" : "NEW HIGH SCORE!");
        sprintf(buf, "Score: %lu", (unsigned long)tet_score);
        TitleText(buf, SCREEN_W / 2, 60, COLOR_GOLD);
        TitleText("Enter your name", SCREEN_W / 2, 82, COLOR_WHITE);
        {
            static const UiHint k[] =
            {
                { UI_ICON_MOVE,   "Letter" },
                { UI_ICON_SELECT, "Next / OK" },
                { UI_ICON_BACK,   "Prev" }
            };
            Ui_DrawHints(k, UI_ARRAY_LEN(k), 226, COLOR_BLACK);
        }
    }

    if(tet_nameDirtyBoxes)
    {
        tet_nameDirtyBoxes = false;
        ch[1] = 0;

        for(i = 0; i < TETRIS_NAME_LEN; i++)
        {
            x   = NAME_BOX_X0 + (int16_t)i * (NAME_BOX_W + NAME_BOX_GAP);
            sel = (i == tet_nameCur);

            Graphics_FillRect(x, NAME_BOX_Y, x + NAME_BOX_W - 1, NAME_BOX_Y + NAME_BOX_H - 1,
                              sel ? COLOR_TETRIS_T_PURPLE : COLOR_TETRIS_GHOST);

            ch[0] = tet_nameCharset[tet_nameIdx[i]];
            TitleText(ch, x + NAME_BOX_W / 2, NAME_BOX_Y + NAME_BOX_H / 2, COLOR_WHITE);
        }
    }
}


// ---- Title screen: update / render ----------------------------------------

// Logic only. Tells Tetris_Update what the player chose.
TitleResult tet_TitleUpdate(void)
{
    int16_t  sy    = TitleStickEdge(g_joy.dy, &tet_titleStickY);    // dy is +DOWN
    bool     up    = (sy < 0);                      // MOVE   = the stick
    bool     down  = (sy > 0);
    bool     tap   = Ui_Select();                   // SELECT = BLUE / stick click
    bool     back  = Ui_Back();                     // BACK   = RED
    uint16_t old;

    if(tet_titleView == TITLE_VIEW_SCORES)
    {
        if(up || down || tap || back)
        {
            tet_titleView      = TITLE_VIEW_MENU;
            tet_titleDirtyFull = true;
        }
        return TITLE_CONTINUE;
    }

    if(back)
        return TITLE_QUIT;

    if(up || down)
    {
        old        = tet_titleSel;
        tet_titleSel = (tet_titleSel + 1) % TITLE_NUM_ROWS;           // only two rows
        tet_titleDirtyRows |= (1 << old) | (1 << tet_titleSel);
        Buzzer_PlaySfx(&sfx_menu_move);
    }

    if(tap)
    {
        Buzzer_PlaySfx(&sfx_menu_select);
        if(tet_titleSel == 0)
            return TITLE_START;

        tet_titleView      = TITLE_VIEW_SCORES;
        tet_titleDirtyFull = true;
    }

    return TITLE_CONTINUE;
}


// Drawing only.
void tet_TitleRender(void)
{
    char     buf[24];
    uint16_t i;

    if(tet_titleDirtyFull)
    {
        tet_titleDirtyFull = false;

        if(tet_titleView == TITLE_VIEW_MENU)
        {
            TitleHeader("TETRIS");
            sprintf(buf, "Best: %lu", (unsigned long)tet_hs.score[0]);
            TitleText(buf, SCREEN_W / 2, 55, COLOR_GOLD);
            {
                static const UiHint k[] =
                {
                    { UI_ICON_MOVE,   "Pick" },
                    { UI_ICON_SELECT, "OK"   },
                    { UI_ICON_BACK,   "Exit" }
                };
                Ui_DrawHints(k, UI_ARRAY_LEN(k), 226, COLOR_BLACK);
            }
            tet_titleDirtyRows = (1 << TITLE_NUM_ROWS) - 1;
        }
        else
        {
            TitleHeader("High Scores");
            TitleDrawScores();
            Ui_HintsAnyKey(226, COLOR_BLACK);
        }
    }

    if(tet_titleView == TITLE_VIEW_MENU)
    {
        for(i = 0; i < TITLE_NUM_ROWS; i++)
            if(tet_titleDirtyRows & (1 << i)) TitleDrawRow(i);
        tet_titleDirtyRows = 0;
    }
}
